package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Buddhism (බුද්ධ ධර්මය).
 * Part 1: Categories 1 to 10 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankBuddhismSets {

  fun getCard(setNum: Int, cardNum: Int, grade: String): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    
    return when (setNum) {
      1 -> when(grade) {
        "10" -> set1_Grade10[(c-1)%set1_Grade10.size]
        "11" -> set10_Grade11[(c-1)%set10_Grade11.size] // චතුරාර්ය සත්‍යය සහ නිවන (11 ශ්‍රේණිය)
        else -> set1_Grade9[(c-1)%set1_Grade9.size]
      }
      2 -> if (grade == "11") set8[(c-1)%set8.size] else set2[(c-1)%set2.size] // සිඟාලෝවාද සූත්‍රය (11) / අභිනිෂ්ක්‍රමණය & බුද්ධත්වය (10)
      3 -> if (grade == "11") set7[(c-1)%set7.size] else set3[(c-1)%set3.size] // ව්‍යග්ඝපජ්ජ සූත්‍රය (11) / ධම්මචක්කප්පවත්තන (10)
      4 -> if (grade == "11") set4_Grade11[(c-1)%set4_Grade11.size] else set4[(c-1)%set4.size] // පරිසර දර්ශනය (11) / අනත්තලක්ඛණ & ආදිත්තපරියාය (10)
      5 -> if (grade == "11") set2_Grade11[(c-1)%set2_Grade11.size] else set5_Grade10[(c-1)%set5_Grade10.size] // ධම්මපදය (11) / මංගල සූත්‍රය (10)
      6 -> if (grade == "11") set3_Grade11[(c-1)%set3_Grade11.size] else set6_Grade10[(c-1)%set6_Grade10.size] // බෞද්ධ මනෝවිද්‍යාව (11) / පරාභව & වසල (10)
      7 -> if (grade == "11") set7_Grade11[(c-1)%set7_Grade11.size] else buddhismGr10Set7_FirstCouncil[(c-1)%buddhismGr10Set7_FirstCouncil.size] // අභිධර්ම මූලධර්ම (11) / ප්‍රථම සංගායනාව (10)
      8 -> if (grade == "11") buddhismGr11Set8_Revival[(c-1)%buddhismGr11Set8_Revival.size] else buddhismGr10Set8_SecondCouncil[(c-1)%buddhismGr10Set8_SecondCouncil.size] // බෞද්ධ පුනරුදය (11) / දෙවන සංගායනාව (10)
      9 -> if (grade == "11") buddhismGr11Set9_BuddhistArt[(c-1)%buddhismGr11Set9_BuddhistArt.size] else buddhismGr10Set9_ThirdCouncil[(c-1)%buddhismGr10Set9_ThirdCouncil.size] // බෞද්ධ කලා ශිල්ප (11) / තෙවන සංගායනාව & අශෝක (10)
      10 -> if (grade == "11") set8_Grade11[(c-1)%set8_Grade11.size] else buddhismGr10Set10_Mahindagamanaya[(c-1)%buddhismGr10Set10_Mahindagamanaya.size] // ජාතක කතා (11) / මහින්දාගමනය (10)
      else -> FlashcardBankBuddhismSetsPart2.getCard(setNum, cardNum, grade)
    }
  }

  // --- SET 1: සිද්ධාර්ථ කුමාරෝත්පත්තිය & ශාක්‍ය වංශය ---
  private val set1_Grade9 = listOf(
    CardContentTuple("සිද්ධාර්ථ කුමාරෝත්පත්තිය සිදුවූයේ කුමන පසළොස්වක පොහෝ දිනකද? ස්ථානය කුමක්ද?", "වෙසක් පුර පසළොස්වක පොහෝ දින, කපිලවස්තු හා දේවදහ නුවර අතර පිහිටි ලුම්බිණි සල් උයනේදීය.", "ක්‍රි.පූ. 623 දී පමණ සිදුවිය. වර්තමාන නේපාලයේ පිහිටා ඇත.", "වෙසක් පෝය • ලුම්බිණි සල් උයන"),
    CardContentTuple("සිද්ධාර්ථ කුමරුගේ දෙමාපියන් සහ වංශය කවුරුන්ද?", "පියා සුද්ධෝදන රජතුමාය; මව මහාමායා දේවියයි. ශාක්‍ය වංශික, සූර්ය වංශික, ගෞතම ගෝත්‍රික විය.", "සුද්ධෝදන රජු ශාක්‍ය ජනපදයේ කපිලවස්තු නුවර පාලනය කළේය.", "සුද්ධෝදන රජු & මහාමායා දේවිය"),
    CardContentTuple("කුමරු උපන් විගස උතුරු දෙසට පියවර හතක් තබා ප්‍රකාශ කළ අභීත ප්‍රකාශය (අසභි වාචාව) කුමක්ද?", "\"අග්ගෝහමස්මි ලෝකස්ස - ජෙට්ඨෝහමස්මි ලෝකස්ස - සෙට්ඨෝහමස්මි ලෝකස්ස - අයමන්තිමා ජාති - නත්ථිදානි පුනබ්භවෝ\"", "\"මම ලොවට අග්‍ර වෙමි, ජ්‍යෙෂ්ඨ වෙමි, ශ්‍රේෂ්ඨ වෙමි, මේ මාගේ අවසන් උපතයි, යළි උපතක් නැත.\"", "අසභි වාචාව • නෙළුම් මල් 7"),
    CardContentTuple("කුමරුගේ ලක්ෂණ බලා අනාගතය ප්‍රකාශ කළ තාපසයා කවුද? ඔහු කළ ප්‍රකාශය කුමක්ද?", "අසිත (කාලදේවල) තවුසා. කුමරු අනිවාර්යයෙන්ම ලොව පහළවන සම්බුදුවරයෙකු වන බව ප්‍රකාශ කර වැඳ වැටුණේය.", "තමන්ට බුදුබව දැකගත නොහැකි වන බැවින් ඔහු සිනාසී පසුව හැඬුවේය.", "අසිත (කාලදේවල) තවුසා"),
    CardContentTuple("නම් තැබීමේ උත්සවයේදී කුමරුට තැබූ නම කුමක්ද? එහි අර්ථය කුමක්ද?", "'සිද්ධාර්ථ' (සියලු අර්ථයන් හා යහපත සිදුකරන තැනැත්තා).", "බමුණන් 108 දෙනෙකු අතුරින් තෝරාගත් අටදෙනෙකු නම් තැබීමට සහභාගී විය.", "සිද්ධාර්ථ = සියලු අර්ථ සිදුකරන්නා"),
    CardContentTuple("නම් තැබීමේදී එක ඇඟිල්ලක් ඔසවා කුමරු ඒකාන්තයෙන්ම බුදුවන බව පැවසූ බාලම බමුණා කවුද?", "කොණ්ඩඤ්ඤ බමුණා (පසුව පස්වග තවුසන්ගේ ප්‍රධානියා වූ අඤ්ඤාකොණ්ඩඤ්ඤ හිමි).", "අනෙක් බමුණන් ඇඟිලි දෙකක් ඔසවා රජෙකු හෝ බුදුවරයෙකු වන බව කීහ.", "කොණ්ඩඤ්ඤ බමුණා"),
    CardContentTuple("කුමරු ඉපිද සත්වන දිනයේ මව්බිසව කළුරිය කළ පසු කුමරු ඇතිදැඩි කළේ කවුද?", "මහා ප්‍රජාපතී ගෝතමී දේවිය (මව්බිසවගේ නැගණිය).", "පසුව කාන්තා ශාසනය පිහිටුවීමට මූලික වූයේද ඇයයි.", "මහා ප්‍රජාපතී ගෝතමිය"),
    CardContentTuple("කුඩා අවධියේ වප්මඟුල් උත්සවයේදී සිද්ධාර්ථ කුමරු අත්කරගත් ධ්‍යාන තත්ත්වය කුමක්ද?", "දඹ රුක් සෙවණේ ආනාපානසති භාවනාව වඩා ප්‍රථම ධ්‍යානය උපදවා ගත්තේය.", "දඹ රුක් සෙවණ සෙලවෙන්නේ නැතිව පැවතීම දුටු සුද්ධෝදන රජු දෙවන වරට වැන්දේය.", "ප්‍රථම ධ්‍යානය • දඹ රුක් සෙවණ"),
